import {esc,fmt} from '../../ui/format.js';
import {TYPES,FIELDS,PROCESS,POOLS,effective} from '../../core/model.js';
import {DIAGRAMS,expandedNeeds,modelAudit} from '../../core/mbse.js';
import {RELATIONS} from '../../core/model.js';
export function variablesView(ctx){const {m,result,baseline,search}=ctx;const n=id=>m.nodes.find(n=>n.id===id);return `<div class="panelhead"><div><h1>Variabile de proiect</h1><p class="muted">O variabilă poate controla mai multe elemente. Legarea cere aceeași unitate.</p></div><button data-action="new-variable">+ Variabilă</button></div><div class="panel tablewrap"><table><thead><tr><th>Nume</th><th>Valoare</th><th>Unitate</th><th>Utilizată de</th><th></th></tr></thead><tbody>${m.variables.map(v=>`<tr><td>${esc(v.name)}</td><td>${fmt(v.value,4)}</td><td>${esc(v.unit)}</td><td>${m.nodes.flatMap(x=>Object.entries(x.bindings).filter(([,id])=>id===v.id).map(([k])=>esc(x.name)+' / '+esc(FIELDS[k][0]))).join('<br>')||'Nelegată — fără efect'}</td><td><button data-var="${esc(v.id)}">Editează</button> <button data-vardelete="${esc(v.id)}">Șterge</button></td></tr>`).join('')}</tbody></table></div><div class="notice">Parametrii fizici au limite verificate. Unitatea «ratio» exprimă probabilități, variații și factori fără dimensiune. Formule arbitrare și conversii automate de unități nu sunt implementate.</div>`}
